'use strict';
// Audited CS 20–21 Review — November 12, 2026.
const SCRIPT_URL='https://script.google.com/macros/s/AKfycbxENUBm5pd966tRn1g9R7HH0zSXcEI10LGLivzQzN0pn6b0ytZHJdV8HU9i0ihYtHJW/exec';
const TITLE='CS 20–21 Fiscal and Monetary Policy Review';
const KEY='gov-cs20-21-review-2026-multitool-v2';
const app=document.getElementById('app');
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
const shuffle=a=>{a=[...a];for(let i=a.length-1;i>0;i--){let j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]];}return a;};
const initial=()=>({started:false,done:false,index:0,items:[],attempts:0,misses:0,name:'',period:'',email:'',start:null,end:null,events:[],sessions:0,tabLeaves:0,copies:0,pastes:0,activeMs:0,awayMs:0,questionSeconds:[],lastSeen:Date.now(),away:false});
let S=initial(), timerId=null,locked=false,feedbackTimeout=null;
const storeKey=mail=>KEY+'::audit20261112::'+mail.toLowerCase();
const now=()=>new Date().toISOString();
const elapsed=()=>S.start?Math.floor(((S.end?new Date(S.end).getTime():Date.now())-new Date(S.start).getTime())/1000):0;
const duration=()=>{let t=elapsed();return Math.floor(t/60)+':'+String(t%60).padStart(2,'0');};
function save(){if(S.email){try{localStorage.setItem(storeKey(S.email),JSON.stringify(S));}catch(e){}}}
function log(type,more={}){S.events.push({type,at:now(),question:S.index+1,...more});if(S.events.length>600)S.events=S.events.slice(-600);save();}
function newRun(){clearTimeout(feedbackTimeout);locked=false;S=initial();S.started=true;S.start=now();S.sessions=1;let positions;do{positions=shuffle(Array.from({length:40},(_,i)=>i%4))}while(positions.some((v,i)=>i>1&&v===positions[i-1]&&v===positions[i-2])||positions.some((v,i)=>i>=7&&positions.slice(i-7,i-3).every((n,j)=>n===positions[i-3+j])));S.items=shuffle(QUESTIONS).map((q,i)=>{let options=shuffle(q.choices.filter(c=>c!==q.answer));options.splice(positions[i],0,q.answer);return {...q,options,missed:false,mastered:false,firstAttempt:null,attemptCount:0,seconds:0,settings:q.targets.map(()=>0),touched:[],selectedText:null}});save();}
function load(mail){try{let v=JSON.parse(localStorage.getItem(storeKey(mail))||'null');if(!v||!Array.isArray(v.items)||v.items.length!==40)return false;S=v;S.sessions=(S.sessions||0)+1;S.started=true;S.away=document.hidden;S.lastSeen=Date.now();while(S.index<40&&S.items[S.index].mastered)S.index++;save();return true;}catch(e){return false;}}
function post(status){accountTime();if(!S.email)return;let first=S.items.filter(q=>q.firstAttempt===true).length,mastered=S.items.filter(q=>q.mastered).length;let payload={action:'save',status,assignmentKey:KEY,assignmentTitle:TITLE,course:'Government',name:S.name,period:S.period,email:S.email,score:mastered,total:40,percent:Math.round(first/40*100),firstAttemptScore:first,masteryScore:mastered,attempts:S.attempts,startedAt:S.start,completedAt:S.end||'',elapsed:duration(),sessions:S.sessions,tabLeaves:S.tabLeaves,copies:S.copies,pastes:S.pastes,activeMs:S.activeMs,awayMs:S.awayMs,questionSeconds:S.items.map(q=>q.seconds||0),events:S.events,gameState:S};fetch(SCRIPT_URL,{method:'POST',mode:'no-cors',headers:{'Content-Type':'text/plain;charset=utf-8'},body:JSON.stringify(payload)}).catch(()=>{});}
function frame(content){app.innerHTML=`<a class="back" href="../../">← Back to Government Hub</a><header class="hero"><div><div class="eyebrow">LEGEND MASTERY SERIES • AMERICAN GOVERNMENT</div><h1>${TITLE}</h1><p>Content Statements 20–21 • Fiscal and Monetary Policy</p><p class="sub">40 OST-style applications. Set each policy tool and choose the best causal explanation. First-attempt accuracy is preserved.</p></div><div class="pills"><span>40 Questions</span><span>2–3 Tools per Case</span><span>Hints after Misses</span><span>Mastery 100%</span></div></header>${content}`;}
function opening(){frame(`<section class="student-panel"><div class="eyebrow">STUDENT INFORMATION</div><h2>Enter your information to begin</h2><p class="sub">Use the same school email to retrieve your saved run.</p><div class="fields"><label>Full name<input id="studentName" placeholder="e.g., Jordan Smith" autocomplete="name"></label><label>Class period<select id="studentPeriod"><option value="">Choose</option>${[1,2,3,4,5,6,7,8].map(n=>`<option value="${n}">${n}</option>`).join('')}</select></label><label>School email<input id="studentEmail" type="email" placeholder="name@school.org" autocomplete="email"></label></div><div class="actions"><button id="start">Start new run</button><button class="secondary" id="load">Load previous work</button></div><p id="notice" role="status"></p></section>`);
const get=()=>({name:document.getElementById('studentName').value.trim(),period:document.getElementById('studentPeriod').value,email:document.getElementById('studentEmail').value.trim().toLowerCase()});
function valid(x){if(!x.name||!x.period||!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(x.email)){document.getElementById('notice').textContent='Please enter your name, class period, and a valid school email.';return false;}return true;}
document.getElementById('start').onclick=()=>{let x=get();if(!valid(x))return;newRun();S.name=x.name;S.period=x.period;S.email=x.email;log('start');post('in_progress');render();};
document.getElementById('load').onclick=()=>{let x=get();if(!x.email){document.getElementById('notice').textContent='Enter the same school email used for your saved run.';return;}if(load(x.email)){log('resume');post(S.done?'submitted':'in_progress');render();return;}document.getElementById('notice').textContent='No saved run found in this browser. You may start a new run.';};}
const tools={fiscal:[['Taxes','Raise taxes','Keep taxes steady','Lower taxes'],['Government spending','Increase spending','Keep spending steady','Decrease spending']],monetary:[['Discount rate (bank borrowing from Fed)','Raise rate','Keep rate steady','Lower rate'],['Reserve requirement (textbook model)','Raise requirement','Keep requirement steady','Lower requirement'],['Open-market operations','Buy bonds','No bond trade','Sell bonds']]};
function slider(q,i){let fiscal=q.kind==='fiscal';let labels=tools[q.kind][i];let names=fiscal?(i===0?['Lower','Steady','Higher']:['Lower','Steady','Higher']):i===2?['Sell','Hold','Buy']:['Lower','Steady','Higher'];return `<div class="lever"><div class="lever-title">${esc(labels[0])}</div><div class="lever-body"><span class="end-label">${names[2]}</span><input class="vertical" type="range" min="-1" max="1" step="1" value="0" data-lever="${i}" aria-label="${esc(labels[0])}"><span class="end-label">${names[0]}</span></div><div class="lever-readout" id="readout${i}">Not set</div><div class="lever-controls"><button type="button" class="nudge" data-lever="${i}" data-set="-1" aria-label="Set ${esc(labels[0])} down">−</button><button type="button" class="nudge" data-lever="${i}" data-set="0" aria-label="Keep ${esc(labels[0])} steady">0</button><button type="button" class="nudge" data-lever="${i}" data-set="1" aria-label="Set ${esc(labels[0])} up">+</button></div></div>`;}
function render(){clearTimeout(feedbackTimeout);locked=false;while(S.index<40&&S.items[S.index]?.mastered)S.index++;if(!S.started){opening();return;}if(S.index>=40){finish();return;}let q=S.items[S.index];let first=S.items.filter(x=>x.firstAttempt===true).length;frame(`<div class="workspace"><section class="question-panel"><div class="eyebrow">${q.kind==='fiscal'?'FISCAL POLICY • CONGRESS':'MONETARY POLICY • FEDERAL RESERVE'}</div><div class="metrics"><div><b>${S.index+1} / 40</b><small>Question</small></div><div><b>${Math.round(first/40*100)}%</b><small>First-attempt score</small></div><div><b>${S.attempts}</b><small>Total attempts</small></div><div><b id="clock">${duration()}</b><small>Elapsed</small></div></div><div class="progress"><span style="width:${S.index/40*100}%"></span></div><h2>${esc(q.stem)}</h2><p class="instruction">Move <b>every</b> slider to match the scenario, including tools that stay unchanged. Use −, 0, or + to confirm each setting, then choose the best explanation. The box is a model, not an answer indicator.</p><div class="model-note">${q.kind==='monetary'?'Historical three-tool model: discount rate, reserve requirement, and bond trades. Actual reserve ratios are currently zero; the Fed now implements policy primarily through administered rates.':'Set net taxes and total government spending relative to the starting policy; spending includes transfers when the case specifies benefits.'}</div><div class="levers ${q.kind}">${q.targets.map((_,i)=>slider(q,i)).join('')}</div><div class="economy"><div class="economy-heading">${q.kind==='fiscal'?'ECONOMIC DEMAND':'MONEY SUPPLY / CREDIT CONDITIONS'}</div><div class="economy-box" id="economyBox"><span>MODEL PREVIEW</span><strong id="boxText">Adjust all tools</strong></div><small>Box size responds to your settings, but it does not reveal whether the settings answer the scenario.</small></div><h3>Which explanation best answers the scenario?</h3><div class="choices">${q.options.map((c,i)=>`<button type="button" class="choice" data-answer="${i}"><span class="letter">${'ABCD'[i]}.</span> ${esc(c)}</button>`).join('')}</div><div class="actions"><button id="apply" disabled>Apply policy and submit answer</button><button id="reset" class="secondary">Restart assignment</button></div><div class="feedback" id="feedback" role="status" aria-live="polite"></div><div class="source"><a href="${esc(q.source)}" target="_blank" rel="noopener noreferrer">Open supporting source ↗</a><div><b>Where to look:</b> ${esc(q.where)}</div>${(q.extraSources||[]).map(src=>`<div class="extra-source"><a href="${esc(src.url)}" target="_blank" rel="noopener noreferrer">${esc(src.label)} ↗</a><div><b>Where to look:</b> ${esc(src.where)}</div></div>`).join('')}</div></section><aside class="side-panel"><div class="eyebrow">HOW TO REASON</div><h3>Work through the entire chain</h3><p>1. Identify the economic problem.</p><p>2. Set each tool—including unchanged tools.</p><p>3. Predict the effect on demand, credit, or inflation.</p><p>4. Compare closely competing explanations.</p><hr><h3>Scoring</h3><p>First attempt is recorded. Incorrect answers receive a hint, and you must correct them for mastery.</p><p><b>Important Fed distinction:</b> Reserve requirements are a textbook tool. Actual U.S. reserve requirement ratios have been zero since March 2020. The discount rate is charged on banks borrowing directly from the Fed; it differs from the federal funds rate between banks.</p><button id="save" class="secondary">Save progress</button><p id="saved" class="sub"></p></aside></div>`);
let touched=new Set(q.touched||[]),vals=q.settings?[...q.settings]:q.targets.map(()=>0),buttons=[...document.querySelectorAll('.choice')];let selected=q.selectedText?q.options.indexOf(q.selectedText):-1;document.querySelectorAll('input.vertical').forEach(el=>el.value=vals[+el.dataset.lever]);if(selected>=0)buttons[selected].classList.add('selected');
function update(){q.targets.forEach((_,i)=>{let value=vals[i],r=document.getElementById('readout'+i);r.textContent=!touched.has(i)?'Not confirmed':i===2&&q.kind==='monetary'?(value===0?'No bond trade':value>0?'Buy bonds':'Sell bonds'):(value===0?'No change':value>0?'Increase':'Decrease');r.classList.toggle('touched',touched.has(i));});let effects=q.kind==='fiscal'?[-vals[0],vals[1]]:[-vals[0],-vals[1],vals[2]],opposed=effects.some(v=>v>0)&&effects.some(v=>v<0);let scale=opposed?1:effects.some(v=>v>0)?1.16:effects.some(v=>v<0)?.84:1;document.getElementById('economyBox').style.transform=`scale(${scale})`;document.getElementById('boxText').textContent=touched.size===q.targets.length?'Model updated':'Adjust all tools';document.getElementById('apply').disabled=touched.size!==q.targets.length||selected<0||locked;q.settings=[...vals];q.touched=[...touched];q.selectedText=selected>=0?q.options[selected]:null;save();}
document.querySelectorAll('input.vertical').forEach(el=>el.oninput=()=>{let i=+el.dataset.lever;vals[i]=+el.value;touched.add(i);update();});document.querySelectorAll('.nudge').forEach(b=>b.onclick=()=>{let i=+b.dataset.lever;vals[i]=+b.dataset.set;touched.add(i);document.querySelector(`input[data-lever="${i}"]`).value=vals[i];update();});buttons.forEach((b,i)=>b.onclick=()=>{if(locked)return;selected=i;buttons.forEach(x=>x.classList.remove('selected'));b.classList.add('selected');update();});
document.getElementById('apply').onclick=()=>{if(locked||touched.size!==q.targets.length||selected<0)return;accountTime();S.attempts++;q.attemptCount++;let toolsCorrect=vals.every((v,i)=>v===q.targets[i]),answerCorrect=q.options[selected]===q.answer,correct=toolsCorrect&&answerCorrect;if(q.firstAttempt===null)q.firstAttempt=correct;if(!correct){q.missed=true;S.misses++;let msg='Check each tool against the case and trace the causal explanation.';document.getElementById('feedback').innerHTML=`<strong>Not yet — try again.</strong><p>${msg} ${esc(q.hint)}</p>`;document.getElementById('feedback').className='feedback hint';log('incorrect',{id:q.id,toolsCorrect,answerCorrect,settings:vals});post('in_progress');return;}locked=true;q.mastered=true;document.querySelectorAll('button.choice,input.vertical,button.nudge,#apply').forEach(x=>x.disabled=true);document.getElementById('feedback').innerHTML=`<strong>Correct — all tools and reasoning align.</strong><p>${esc(q.explain)}</p>`;document.getElementById('feedback').className='feedback good';log('correct',{id:q.id,firstTry:!q.missed});post('in_progress');feedbackTimeout=setTimeout(()=>{S.index++;save();render();},2200);};
document.getElementById('reset').onclick=()=>{if(confirm('Restart all 40 questions? Previous first-attempt results already submitted remain recorded.')){let x={name:S.name,period:S.period,email:S.email};newRun();Object.assign(S,x);log('restart');post('in_progress');render();}};document.getElementById('save').onclick=()=>{log('manual_save');post('in_progress');document.getElementById('saved').textContent='Saved in this browser. A teacher submission was attempted; receipt cannot be confirmed here.';};if(q.missed){document.getElementById('feedback').innerHTML=`<strong>Hint</strong><p>${esc(q.hint)}</p>`;document.getElementById('feedback').className='feedback hint'}update();}
function finish(){accountTime();S.done=true;if(!S.end){S.end=now();log('complete');post('submitted');}let first=S.items.filter(q=>q.firstAttempt===true).length;app.innerHTML=`<a class="back" href="../../">← Back to Government Hub</a><section class="completion"><div class="eyebrow">COMPLETION TICKET • MASTERY</div><h1>${esc(TITLE)}</h1><div class="ticket-priority"><div><span>STUDENT NAME</span><strong class="ticket-name">${esc(S.name)}</strong></div><div><span>TOTAL ATTEMPTS</span><strong class="ticket-attempts">${S.attempts}</strong></div></div><p>Period ${esc(S.period)} • ${esc(S.email)}</p><div class="metrics ticket-metrics"><div><b>${first}/40 (${Math.round(first/40*100)}%)</b><small>First-attempt score</small></div><div><b>40/40 • 100%</b><small>Mastery</small></div><div><b>${duration()}</b><small>Elapsed time</small></div></div><p class="sub">Started: ${esc(new Date(S.start).toLocaleString())}<br>Completed: ${esc(new Date(S.end).toLocaleString())}<br>Active: ${Math.round(S.activeMs/1000)}s • Away: ${Math.round(S.awayMs/1000)}s • Sessions: ${S.sessions}<br>Tab leaves: ${S.tabLeaves} • Copies: ${S.copies} • Pastes: ${S.pastes}</p><p class="sub">Screenshot this entire ticket and attach it in Google Classroom.</p></section><div class="actions"><button id="again" class="secondary">Start a new run</button></div>`;document.getElementById('again').onclick=()=>{if(!confirm('Start a new run? Save your ticket screenshot first.'))return;let x={name:S.name,period:S.period,email:S.email};newRun();Object.assign(S,x);log('restart');post('in_progress');render();};}
function accountTime(){if(!S.started||S.done)return;let current=Date.now(),dt=Math.max(0,current-(S.lastSeen||current));if(S.away)S.awayMs+=dt;else{S.activeMs+=dt;if(S.items[S.index]&&!S.items[S.index].mastered)S.items[S.index].seconds=(S.items[S.index].seconds||0)+dt/1000}S.lastSeen=current}
setInterval(()=>{if(S.started&&!S.done){accountTime();let el=document.getElementById('clock');if(el)el.textContent=duration();save();}},1000);
document.addEventListener('visibilitychange',()=>{if(!S.started||S.done)return;accountTime();S.away=document.hidden;if(S.away)S.tabLeaves++;log(S.away?'tab_leave':'tab_return');});document.addEventListener('copy',()=>{if(S.started&&!S.done){S.copies++;log('copy');}});document.addEventListener('paste',()=>{if(S.started&&!S.done){S.pastes++;log('paste');}});window.addEventListener('beforeunload',()=>{accountTime();save()});
opening();
